import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse(`{"title":"MiniMax Code learning map","description":"MiniMax Code is MiniMax's first-party coding agent. This directory covers Code only. Agent, Hailuo, and Talkie stay as one-line map entries.","frontmatter":{"title":"MiniMax Code learning map","description":"MiniMax Code is MiniMax's first-party coding agent. This directory covers Code only. Agent, Hailuo, and Talkie stay as one-line map entries.","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"products/minimax-code/index.md","filePath":"products/minimax-code/index.md","lastUpdated":1787110548000}`),i={name:"products/minimax-code/index.md"};function o(s,t,d,l,p,c){return n(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="minimax-code-learning-map" tabindex="-1">MiniMax Code learning map <a class="header-anchor" href="#minimax-code-learning-map" aria-label="Permalink to &quot;MiniMax Code learning map&quot;">​</a></h1><blockquote><p><strong>MiniMax Code</strong> is MiniMax&#39;s first-party coding agent. The international homepage calls it &quot;The coding harness built for MiniMax models&quot; (<a href="https://www.minimax.io/" target="_blank" rel="noreferrer">minimax.io</a>). The product docs say: &quot;MiniMax Code is a desktop AI Agent app that brings chat, project context, file operations, terminal sessions, browser previews, skills, memory, and automation into one local workspace&quot; (<a href="https://agent.minimax.io/docs/code/welcome" target="_blank" rel="noreferrer">Welcome</a>).</p><p>The same product also ships as <strong>MiniMax Code CLI</strong>. The executable is <code>mcode</code> (<a href="https://agent.minimax.io/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI Quick Start</a>). That is not a second product.</p></blockquote><h2 id="product-family-retrieve" tabindex="-1">Product family (Retrieve) <a class="header-anchor" href="#product-family-retrieve" aria-label="Permalink to &quot;Product family (Retrieve)&quot;">​</a></h2><p>List official first-level entries first, then decide what this site writes. Every row comes from the homepage nav, About, footer, or docs index opened on 2026-08-19.</p><table tabindex="0"><thead><tr><th>Official first-level entry</th><th>Official URL</th><th>This site</th></tr></thead><tbody><tr><td><strong>MiniMax Code</strong></td><td><a href="https://agent.minimax.io/docs/code/welcome" target="_blank" rel="noreferrer">Welcome</a>, <a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">Download</a>, <a href="https://agent.minimax.io/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI</a></td><td><strong>Standalone pages</strong> (this directory)</td></tr><tr><td>MiniMax Agent</td><td><a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a> / <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a></td><td>One map line. Web general agent; full write-up is <a href="https://github.com/zenHeart/learn-ai/issues/73" target="_blank" rel="noreferrer">#73</a></td></tr><tr><td>MiniMax Design</td><td><a href="https://design.minimax.io/" target="_blank" rel="noreferrer">design.minimax.io</a></td><td>One map line. Commercial content, not a coding agent</td></tr><tr><td>MiniMax Hub</td><td>Still used on the CN About nav (<a href="https://www.minimaxi.com/about" target="_blank" rel="noreferrer">about</a>)</td><td>One map line. Name collision with Design; no second tutorial</td></tr><tr><td>MiniMax Audio</td><td><a href="https://www.minimax.io/audio" target="_blank" rel="noreferrer">minimax.io/audio</a></td><td>One map line. Speech and music</td></tr><tr><td>Hailuo / MiniMax H3</td><td><a href="https://hailuoai.video/" target="_blank" rel="noreferrer">hailuoai.video</a>, <a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">models intro</a></td><td>One map line. Video generation</td></tr><tr><td>Talkie</td><td>International Product nav (<a href="https://www.minimax.io/" target="_blank" rel="noreferrer">minimax.io</a>)</td><td>One map line. Character / companion app</td></tr><tr><td>星野 (Xingye)</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">xingyeai.com</a></td><td>One map line. CN counterpart of Talkie</td></tr><tr><td>MiniMax M3 and other models</td><td><a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">models-intro</a></td><td>One map line. Models are not a product tutorial</td></tr><tr><td>Token Plan / API</td><td><a href="https://platform.minimax.io/" target="_blank" rel="noreferrer">platform.minimax.io</a></td><td>One map line. Developer platform</td></tr><tr><td>Use MiniMax in AI coding tools</td><td><a href="https://platform.minimax.io/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">text-ai-coding-tools</a> (CN twin: <a href="https://platform.minimaxi.com/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">minimaxi.com</a>)</td><td>One map line. Point M3 at Claude Code / Cursor. <strong>Not</strong> MiniMax Code</td></tr></tbody></table><p>Sources: <a href="https://www.minimax.io/" target="_blank" rel="noreferrer">minimax.io</a>, <a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">minimaxi.com</a>, <a href="https://www.minimaxi.com/about" target="_blank" rel="noreferrer">minimaxi.com/about</a>, <a href="https://agent.minimax.io/docs/llms.txt" target="_blank" rel="noreferrer">agent.minimax.io/docs/llms.txt</a>, <a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">models-intro</a>.</p><p><strong>This directory&#39;s job:</strong> MiniMax Code only. Other MiniMax AI products do not get full tutorials here.</p><p><strong>Names that collide:</strong></p><ul><li><strong>MiniMax Code ≠ MiniMax Agent.</strong> Changelog v3.0.33 renamed the desktop app to MiniMax Code. The web product is still Agent. The docs site is still branded &quot;MiniMax Agent Docs&quot;.</li><li><strong><code>mcode</code> ≠ the <code>minimax</code> shortcut in that changelog.</strong> The official CLI command is <code>mcode</code>.</li><li><strong>Putting MiniMax-M3 inside Claude Code ≠ installing MiniMax Code.</strong></li><li><strong>Coding / Work are desktop modes, not products.</strong></li></ul><p>See the <a href="./minimax-code-glossary.html">glossary</a>.</p><h3 id="decision-tree" tabindex="-1">Decision tree <a class="header-anchor" href="#decision-tree" aria-label="Permalink to &quot;Decision tree&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do you need?</span></span>
<span class="line"><span>├── Edit a local repo / fix bugs / inspect diffs / run commands</span></span>
<span class="line"><span>│   └── → MiniMax Code</span></span>
<span class="line"><span>│       ├── GUI, browser preview, schedules, phone remote?</span></span>
<span class="line"><span>│       │     → Desktop app (download page)</span></span>
<span class="line"><span>│       ├── Terminal TUI / scripts / CI / editor ACP?</span></span>
<span class="line"><span>│       │     → CLI (\`mcode\`)</span></span>
<span class="line"><span>│       └── Split work across specialist agents?</span></span>
<span class="line"><span>│             → Agent Team inside the same product</span></span>
<span class="line"><span>├── Long-horizon work in the browser, not necessarily a local repo</span></span>
<span class="line"><span>│   └── → MiniMax Agent (#73; not this directory)</span></span>
<span class="line"><span>├── Keep Claude Code / Cursor and only swap in MiniMax-M3</span></span>
<span class="line"><span>│   └── → Open Platform &quot;AI coding tools&quot; guide, not this product</span></span>
<span class="line"><span>├── Video</span></span>
<span class="line"><span>│   └── → Hailuo / MiniMax H3 / MiniMax Design</span></span>
<span class="line"><span>├── Speech / music</span></span>
<span class="line"><span>│   └── → MiniMax Audio</span></span>
<span class="line"><span>└── Character chat</span></span>
<span class="line"><span>    └── → Talkie (intl) or 星野 (CN)</span></span></code></pre></div><h2 id="two-surfaces" tabindex="-1">Two surfaces <a class="header-anchor" href="#two-surfaces" aria-label="Permalink to &quot;Two surfaces&quot;">​</a></h2><p>Official CLI docs: the desktop client is for &quot;graphical task management and result review&quot;; the CLI is closer to &quot;repositories, the terminal, scripts, CI, and editors&quot; (<a href="https://agent.minimax.io/docs/cli/features" target="_blank" rel="noreferrer">Features</a>).</p><table tabindex="0"><thead><tr><th>Surface</th><th>Entry</th><th>Use when</th></tr></thead><tbody><tr><td>Desktop</td><td><a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">International download</a> / <a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">CN download</a></td><td>Tasks, workspace, browser, schedules, Remote Control</td></tr><tr><td>CLI · TUI</td><td><code>mcode</code></td><td>Ongoing repo work in a terminal</td></tr><tr><td>CLI · Headless</td><td><code>mcode exec</code></td><td>Scripts and CI</td></tr><tr><td>CLI · ACP</td><td><code>mcode acp</code></td><td>Embed in an ACP host such as Zed</td></tr></tbody></table><p>The desktop app also has Coding / Work <strong>modes</strong> (same agent, different tool exposure). See the <a href="./minimax-code.html">tutorial</a>.</p><h2 id="when-it-is-worth-trying" tabindex="-1">When it is worth trying <a class="header-anchor" href="#when-it-is-worth-trying" aria-label="Permalink to &quot;When it is worth trying&quot;">​</a></h2><p><strong>Try it if</strong></p><ul><li>You want a first-party agent, not just another model plugged into a third-party tool.</li><li>You want one desktop workspace for the repo, terminal, browser, skills, and memory.</li><li>You want <code>mcode</code> in the terminal: TUI, <code>exec</code>, ACP.</li><li>You already have a MiniMax account or a Token Plan. The M3 post says: &quot;MiniMax Code can be used with MiniMax Token Plans.&quot;</li></ul><p><strong>Wait if</strong></p><ul><li>You only want MiniMax-M3 inside Claude Code / Cursor — use the <a href="https://platform.minimax.io/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">Open Platform guide</a>.</li><li>You want the web general agent — that is MiniMax Agent (#73).</li><li>You want video or character chat — Hailuo / Talkie, not Code.</li><li>You need a Linux desktop client — official desktop docs list macOS and Windows only. The CLI supports macOS, Windows, common Linux distros, and WSL. Alpine / musl is not supported.</li></ul><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Goal</th></tr></thead><tbody><tr><td>1. Install</td><td><a href="./minimax-code.html">Tutorial</a> desktop or CLI install</td><td>Send the first task after sign-in</td></tr><tr><td>2. Modes and workspace</td><td>Tutorial: Coding / Work, workspace, permissions</td><td>Let it edit local code</td></tr><tr><td>3. Workflows</td><td><a href="./minimax-code-cookbook.html">Cookbook</a></td><td>Agent Team, <code>mcode exec</code>, ACP</td></tr><tr><td>4. Look up</td><td><a href="./minimax-code-cheatsheet.html">Cheatsheet</a></td><td>Commands, slash, permission tiers, official links</td></tr><tr><td>5. Names</td><td><a href="./minimax-code-glossary.html">Glossary</a></td><td>Code vs Agent, desktop vs CLI, orthogonal modes</td></tr></tbody></table><h2 id="feature-index" tabindex="-1">Feature index <a class="header-anchor" href="#feature-index" aria-label="Permalink to &quot;Feature index&quot;">​</a></h2><p>Only capabilities that have official doc pages.</p><table tabindex="0"><thead><tr><th>Capability</th><th>One line</th><th>Official page</th></tr></thead><tbody><tr><td>Coding / Work</td><td>Same agent, different tool exposure</td><td><a href="https://agent.minimax.io/docs/code/workflows/modes" target="_blank" rel="noreferrer">modes</a></td></tr><tr><td>Workspace</td><td>Attach a local project directory</td><td><a href="https://agent.minimax.io/docs/code/workflows/workspace" target="_blank" rel="noreferrer">workspace</a></td></tr><tr><td>Permissions</td><td>Confirm file, command, and external actions</td><td><a href="https://agent.minimax.io/docs/code/workflows/permissions" target="_blank" rel="noreferrer">permissions</a></td></tr><tr><td>Agent Team</td><td>Split complex work across specialist agents</td><td><a href="https://agent.minimax.io/docs/code/agents/team" target="_blank" rel="noreferrer">team</a></td></tr><tr><td>Skills / memory / custom agents</td><td>Reuse workflows and keep preferences</td><td><a href="https://agent.minimax.io/docs/llms.txt" target="_blank" rel="noreferrer">llms.txt desktop tree</a></td></tr><tr><td>Schedules / Remote Control / IM</td><td>Recurring jobs, phone remote, chat apps</td><td>Desktop <code>/docs/code/automation/*</code></td></tr><tr><td>CLI TUI / exec / acp</td><td>Terminal, scripts, editors</td><td><a href="https://agent.minimax.io/docs/cli/features" target="_blank" rel="noreferrer">features</a></td></tr><tr><td>Token Plan and check-in credits</td><td>See in-product usage</td><td><a href="https://agent.minimax.io/docs/code/account/usage" target="_blank" rel="noreferrer">usage</a></td></tr></tbody></table><p>Model internals (MSA, training, benchmarks) stay out of this directory. See <a href="/tech/fundamentals/LLM.html">Learn LLM</a> and the <a href="https://www.minimax.io/blog/minimax-m3" target="_blank" rel="noreferrer">M3 post</a>.</p>`,27)])])}const x=e(i,[["render",o]]);export{u as __pageData,x as default};
